<?php
function reportTypes(): array {return ['sales'=>'Daily sales','products'=>'Product sales','portions'=>'Prepared food & waste','inventory'=>'Current ingredient stock','purchases'=>'Purchases by supplier','expenses'=>'Operating expenses','cash'=>'Cash reconciliation','refills'=>'Rice refill usage'];}
function reportData(string $type,string $from,string $to): array {
    need(['Owner']);choice($type,array_keys(reportTypes()));dateval($from);dateval($to);if($from>$to)throw new RuntimeException('The start date must not be after the end date.');$range=[$from,$to.' 23:59:59'];
    switch($type){
    case 'sales':return [['Date','Transactions','Sales PHP','Average sale PHP'],rows('SELECT DATE(sold_at) day,COUNT(*) orders,SUM(total_amount) sales,ROUND(AVG(total_amount),2) average FROM sales WHERE sold_at BETWEEN ? AND ? GROUP BY DATE(sold_at) ORDER BY day DESC',$range)];
    case 'products':return [['Product','Quantity sold','Revenue PHP'],rows('SELECT i.item_name_snapshot,SUM(i.quantity) qty,SUM(i.quantity*i.unit_price) revenue FROM sale_items i JOIN sales s ON s.sale_id=i.sale_id WHERE s.sold_at BETWEEN ? AND ? GROUP BY i.item_name_snapshot ORDER BY revenue DESC',$range)];
    case 'portions':return [['Date','Product','Prepared','Served','Wasted','Remaining'],rows("SELECT d.menu_date,m.name,d.prepared_qty,COALESCE(s.served,0) served,d.wasted_qty,d.prepared_qty-d.wasted_qty-COALESCE(s.served,0) remaining FROM daily_menu_items d JOIN menu_items m ON m.menu_item_id=d.menu_item_id LEFT JOIN (SELECT daily_menu_item_id,SUM(quantity) served FROM sale_item_components GROUP BY daily_menu_item_id) s ON s.daily_menu_item_id=d.daily_menu_item_id WHERE d.menu_date BETWEEN ? AND ? AND m.item_type<>'combo' ORDER BY d.menu_date DESC,m.name",[$from,$to])];
    case 'inventory':return [['Ingredient','On hand now','Unit','Reorder level','Active'],rows('SELECT i.name,COALESCE(m.balance,0) balance,u.symbol,i.reorder_level,IF(i.is_active=1,\'Yes\',\'No\') active FROM inventory_items i JOIN units u ON u.unit_id=i.unit_id LEFT JOIN (SELECT inventory_item_id,SUM(quantity_change) balance FROM stock_movements GROUP BY inventory_item_id) m ON m.inventory_item_id=i.inventory_item_id ORDER BY i.name')];
    case 'purchases':return [['Supplier','Posted receipts','Total PHP'],rows("SELECT s.name,COUNT(*) receipts,SUM(t.total) total FROM stock_receipts r JOIN suppliers s ON s.supplier_id=r.supplier_id JOIN (SELECT stock_receipt_id,SUM(ROUND(quantity*unit_cost,2)) total FROM stock_receipt_items GROUP BY stock_receipt_id) t ON t.stock_receipt_id=r.stock_receipt_id WHERE r.status='posted' AND r.posted_at BETWEEN ? AND ? GROUP BY s.supplier_id,s.name ORDER BY total DESC",$range)];
    case 'expenses':return [['Paid at','Category','Description','Amount PHP','Source'],rows('SELECT e.paid_at,c.name,e.description,e.amount,e.payment_source FROM expenses e JOIN expense_categories c ON c.expense_category_id=e.expense_category_id WHERE paid_at BETWEEN ? AND ? ORDER BY paid_at DESC',$range)];
    case 'refills':return [['Date','Rice product','Refill portions'],rows("SELECT DATE(c.served_at) day,m.name,SUM(c.quantity) portions FROM sale_item_components c JOIN daily_menu_items d ON d.daily_menu_item_id=c.daily_menu_item_id JOIN menu_items m ON m.menu_item_id=d.menu_item_id WHERE c.serving_type='refill' AND c.served_at BETWEEN ? AND ? GROUP BY DATE(c.served_at),m.menu_item_id,m.name ORDER BY day DESC",$range)];
    case 'cash':$out=[];foreach(rows('SELECT c.*,u.full_name FROM cash_sessions c JOIN users u ON u.user_id=c.user_id WHERE opened_at BETWEEN ? AND ? ORDER BY cash_session_id DESC',$range)as $s){$t=sessionTotals((int)$s['cash_session_id']);$out[]=[$s['cash_session_id'],$s['full_name'],$s['status'],$s['opening_float'],dec($t['sales']),dec($t['purchases']+$t['expenses']),dec($t['expected']),$s['counted_cash']??'',$s['counted_cash']===null?'':dec(cents($s['counted_cash'])-$t['expected'])];}return [['Session','Cashier','Status','Opening PHP','Sales PHP','Paid out PHP','Expected PHP','Counted PHP','Variance PHP'],$out];
    }
    return [[],[]];
}
function reportsView(): void {
    $type=choice($_GET['type']??'sales',array_keys(reportTypes()));$from=dateval($_GET['from']??date('Y-m-01'));$to=dateval($_GET['to']??today());[$headers,$r]=reportData($type,$from,$to);
    heading('A BETTER VIEW OF YOUR BUSINESS','Reports & insights','Real records. Useful answers. Ready to print or export.','<button type="button" class="btn ghost" data-print>Print report</button>');
    echo '<form class="report-filters filters" method="get"><input type="hidden" name="page" value="reports">';selectField('Report','type',reportTypes(),$type);field('From','from','date',$from,'required');field('To','to','date',$to,'required');echo '<button class="btn primary">View report</button><a class="btn ghost" href="?'.h(http_build_query(['page'=>'reports','type'=>$type,'from'=>$from,'to'=>$to,'export'=>'csv'])).'">Export CSV ↓</a></form>';
    echo '<section class="panel"><div class="panel-head"><div><h2>'.h(reportTypes()[$type]).'</h2><p>'.($type==='inventory'?'Current balance across all movements; date filters do not apply.':h($from).' to '.h($to)).'</p></div>'.badge(count($r).' rows').'</div>';tableView($headers,array_map(fn($x)=>array_map(fn($v)=>h($v),array_values($x)),$r),'No matching activity in this period.',false);echo '</section><p class="hint">Cash summaries are operational reports, not accounting profit. Product revenue includes combo sales once; free refills generate no additional revenue.</p>';
}
function auditView(): void {
    heading('A TRACEABLE WORKSPACE','Activity log','Important actions, recorded with the person responsible.');filterBar('Search action, record, or team member…');$data=[];foreach(rows('SELECT a.*,u.full_name FROM audit_logs a JOIN users u ON u.user_id=a.user_id ORDER BY audit_log_id DESC LIMIT 1000')as $a)if(matches($a['action'].' '.$a['entity_name'].' '.$a['full_name'].' '.$a['record_id']))$data[]=[h($a['created_at']),h($a['full_name']),badge(str_replace('_',' ',$a['action'])),h($a['entity_name'].' #'.$a['record_id']),h($a['reason']??'—'),'<details><summary>Changes</summary><pre>'.h('Before: '.($a['old_values']??'—')."\nAfter: ".($a['new_values']??'—')).'</pre></details>'];echo '<section class="panel">';tableView(['Time','User','Action','Record','Reason','Details'],$data);echo '</section><p class="hint">Shows the latest 1,000 events. All events remain in the database.</p>';
}
function profileView(): void {
    $u=need();heading('YOUR ACCOUNT','My profile','Update your name or choose a new password.');echo '<section class="panel narrow"><div class="panel-head"><h2>'.h($u['username']).'</h2>'.badge($u['role_name'],'green').'</div>';formStart('profile_save');field('Full name','full_name','text',$u['full_name'],'required maxlength="100"');field('Current password','current_password','password','','required autocomplete="current-password"');field('New password (optional)','password','password','','minlength="10" maxlength="72" autocomplete="new-password"');formEnd('Save profile');echo '</section>';
}
function settingsView(): void {
    heading('MADE FOR YOUR DAILY ROUTINE','Workspace guide','A practical guide to running CarinderEase.');echo '<div class="guide-grid">';
    $cards=[['01','Before opening','Set up your team, product catalog, combo components, suppliers, ingredient units, and expense categories. Publish today’s menu with prices and cumulative prepared portions.'],['02','At the counter','Open your cash drawer with the float actually in it. Select dishes in Counter POS, choose dine-in or takeout, and enter the cash received. Complete the sale before handing over the meal.'],['03','In the kitchen','Record raw ingredients issued to cooking in Stock movements. Update prepared portions in Today’s menu. Record a rice refill from the active meal card; close the visit when the guest leaves.'],['04','When supplies arrive','Start a receipt, add the ingredients in base units, and check the quantities and costs. Post once when received and paid. Choose whether cash came from the drawer or the owner.'],['05','At closing time','Record prepared-food waste and any operating expenses. Count the actual cash and close your own session. Review the variance, daily sales, portion usage, and stock alerts.'],['06','Keep your records safe','Use phpMyAdmin Export to back up the database regularly. Refer to README.md for installation, restore steps, and the test results. Keep passwords private and deactivate former staff accounts.']];foreach($cards as [$n,$t,$body])echo '<section class="panel guide-card"><span class="step-number">'.$n.'</span><h2>'.h($t).'</h2><p>'.h($body).'</p></section>';echo '</div><section class="panel"><div class="panel-head"><h2>Your workspace scope</h2></div><p>One branch · One cash drawer · Cash payments · Fixed combos · Dine-in rice refills · 20 database tables</p><p class="muted">The initial version does not process refunds, supplier credit, customer utang, delivery, or online payments. Completed financial records are immutable. Sample starter data is intended for demonstration; use a fresh installation without sample data for actual records.</p></section>';
}
